{
  "aggregate_id": "DEF-LVMC-11-02-070::commercial_vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The definition requires a motor vehicle or motor-vehicle-and-trailer combination, while human-powered devices are excluded from the underlying vehicle definition."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "Being designed to carry many passengers does not establish primary maintenance or use for the furtherance of a commercial enterprise."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "A pedestrian child is a person rather than a motor vehicle or motor-vehicle-and-trailer combination."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "A commercial mass classification or licensing marking does not establish the definition's required primary commercial maintenance or use."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric bicycles, leaving them outside the motor vehicles and combinations admitted by the controlling definition."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The motor-vehicle definition expressly excludes electric scooters, leaving them outside the motor vehicles and combinations admitted by the controlling definition."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Designation as an emergency vehicle does not determine whether the vehicle is maintained or used primarily for a commercial enterprise."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting function does not establish or negate the required primary commercial maintenance or use."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The moped contract does not settle the primary commercial maintenance or use required by the controlling definition."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Self-propulsion and nonrail operation do not establish whether the vehicle satisfies the additional primary-commercial-purpose requirement."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The motorcycle contract establishes a motor-vehicle type but does not settle its primary commercial maintenance or use."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service does not by itself settle whether the vehicle is maintained or used primarily for a commercial enterprise."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person, including a person using a wheelchair or qualifying device, rather than a motor vehicle or motor-vehicle-and-trailer combination."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "A pedestrian using the specified assistance remains a person rather than either kind of vehicle admitted by the controlling definition."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle definition requires that the vehicle not be operated upon rails, whereas this contract describes rail equipment."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "School-bus designation and markings do not determine whether its primary maintenance or use furthers a commercial enterprise."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The for-hire contract does not itself settle the definition's requirement that maintenance or use be primarily for the furtherance of a commercial enterprise."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "The contract's alternatives do not establish primary commercial maintenance or use for every member of the class."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The contract includes drawn units as well as combinations and does not establish either the required motor-vehicle-and-trailer configuration or its primary commercial purpose."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Public transit service does not establish whether the bus is maintained or used primarily for the furtherance of a commercial enterprise."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A body built to carry goods does not determine whether the truck is maintained or used primarily for a commercial enterprise."
    }
  ]
}

